<?php
declare(strict_types=1);
namespace Sentinel\Tests\Unit\Services;
use PDO; use PHPUnit\Framework\TestCase; use Sentinel\Core\Config; use Sentinel\Core\Database; use Sentinel\Core\HttpException; use Sentinel\Core\RuntimeContext; use Sentinel\Repositories\AuditRepository; use Sentinel\Repositories\DeviceRepository; use Sentinel\Services\AuditService; use Sentinel\Services\DeviceManagementService;
final class DeviceManagementServiceTest extends TestCase { private function service():array{$db=new Database(new Config(['database'=>[]]),static fn():PDO=>new PDO('sqlite::memory:',null,null,[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]));$db->execute('CREATE TABLE devices (device_id INTEGER PRIMARY KEY AUTOINCREMENT,device_uuid TEXT UNIQUE,company_id INTEGER,device_name TEXT,device_type TEXT,platform TEXT,device_identifier TEXT,device_status TEXT,last_seen_at TEXT,created_at TEXT,updated_at TEXT,deleted_at TEXT,UNIQUE(company_id,device_identifier))');$db->execute('CREATE TABLE audit_logs (audit_log_id INTEGER PRIMARY KEY,company_id INTEGER,user_id INTEGER,entity_name TEXT,entity_id TEXT,action_name TEXT,action_status TEXT,ip_address TEXT,user_agent TEXT,old_values TEXT,new_values TEXT,metadata TEXT)');$context=new RuntimeContext();$context->setTenantId(101);$context->setUser('7');return [new DeviceManagementService(new DeviceRepository($db,$context),new AuditService(new AuditRepository($db,$context),$context)),$db];} public function testCreateUpdateAndAuditAreSafe():void{[$service,$db]=$this->service();try{$service->createDevice(['device_name'=>'Rejected','device_type'=>'ANDROID','platform'=>'ANDROID','device_identifier'=>'rejected','company_id'=>202]);self::fail();}catch(HttpException $e){self::assertSame(422,$e->statusCode());}$device=$service->createDevice(['device_name'=>'Patrol One','device_type'=>'ANDROID','platform'=>'ANDROID','device_identifier'=>'android-1','device_status'=>'ACTIVE']);self::assertSame('101',(string)$device['company_id']);$updated=$service->updateDevice((string)$device['device_id'],['device_status'=>'RETIRED']);self::assertSame('RETIRED',$updated['device_status']);try{$service->updateDevice((string)$device['device_id'],['device_status'=>'ACTIVE']);self::fail();}catch(HttpException $e){self::assertSame(422,$e->statusCode());}self::assertSame('2',(string)$db->fetch('SELECT COUNT(*) total FROM audit_logs')['total']);} }